async function RT_ALARM_CHK(parm = 0) {
  let val = 0, rtn = (-1), r_ptr = 0, r_cnt = 0, t_ptr = 0, hrs = 0, min = 0, sec = 0, day = 0, t_time = 0;
  g.RUN_SMELL_ETHERIUM$ = false;
  if (!(g.GL_ALARM_WAIT == 0)) {
    g.GL_ALARM_WAIT = false;
    return false;
  } else if (!(g.GL_ALARM_STOP == 0)) {
    return false;
  }
  await RT_COPY_TIME(GL_TIME, GL_TEMP_TIME);
  loop1: for (;;) {
    if (r_ptr == K_A_RSIZE) {
      if (rtn == (-1)) {
        if (g.RUN_SMELL_ETHERIUM$) {
          break loop1;
        }
        return r_cnt;
      } else {
        r_ptr = rtn;
        rtn = get(GL_A_ROUT, r_ptr);
        t_ptr = r_ptr * K_A_TWDTH;
        put(GL_A_ROUT, r_ptr, 0);
        t_time = GL_A_TIME + t_ptr;
        sec = getb(t_time, K_SEC);
        min = getb(t_time, K_MIN);
        hrs = getb(t_time, K_HRS);
        day = getb(t_time, K_DAY);
        copyTable(t_time, 0, K_A_TWDTH);
        if (!(hasFlag(CH_PLAYER, FL_ASLEEP))) {
          await RT_UPDATE_STATUS_LINE();
        }
        g.GL_ALARM_EXEC = true;
        val = await apply(rtn);
        if (g.RUN_SMELL_ETHERIUM$) {
          break loop1;
        }
        g.GL_ALARM_EXEC = false;
        await RT_COPY_TIME(GL_TEMP_TIME, GL_TIME);
        ++r_cnt;
        if (!(val == 0) && eq(await RT_CLOCK_CMP(hrs, min, sec, day), -1)) {
          if (parm == 1) {
            tell("[Press any key to continue.]\n");
            await readChar(1);
          } else if (parm == 2) {
            loop2: for (;;) {
              tell("\nDo you want to continue waiting?\nPlease press Y or N > ");
              val = await readChar(1);
              printC(val);
              crlf();
              if ((val == 78 /* "N" */ || val == 110 /* "n" */)) {
                rtn = -1;
                r_ptr = K_A_RSIZE;
                await RT_DO_CLOCK_SET(GL_TIME, hrs, min, sec, day);
                break loop2;
              } else if ((val == 89 /* "Y" */ || val == 121 /* "y" */)) {
                break loop2;
              }
            }
          }
        }
        if (rtn == (-1)) {
          continue loop1;
        }
        rtn = -1;
        r_ptr = 0;
        continue loop1;
      }
    }
    if (!(get(GL_A_ROUT, r_ptr) == 0)) {
      t_ptr = r_ptr * K_A_TWDTH;
      sec = getb(GL_A_TIME, t_ptr + K_SEC);
      min = getb(GL_A_TIME, t_ptr + K_MIN);
      hrs = getb(GL_A_TIME, t_ptr + K_HRS);
      day = getb(GL_A_TIME, t_ptr + K_DAY);
      if ((!(parm == 0) && eq(await RT_CLOCK_CMP(hrs, min, sec, day), -1)) || ((parm == 0) && eq(await RT_CLOCK_CMP(hrs, min, sec, day), -1, 0))) {
        await RT_DO_CLOCK_SET(GL_TIME, hrs, min, sec, day);
        rtn = r_ptr;
      }
    }
    ++r_ptr;
  }
  if (g.RUN_SMELL_ETHERIUM$) {
    await RT_SMELL_ETHERIUM$();
    return r_cnt;
  } else {
    return false;
  }
}

