async function RT_GET_PREP(syn, which) {
  let prep = 0;
  if (which == 1) {
    prep = getb(syn, K_P_SPREP1);
  } else {
    prep = getb(syn, K_P_SPREP2);
  }
  if ((prep = prep & 63) == 0) {
    return 0;
  } else {
    return prep + 192;
  }
}

async function RT_SYNTAX_CHECK() {
  let syn = 0, len = 0, num = 0, obj = 0, drive1 = false, drive2 = false, prep = 0, verb = 0, tprep = 0;
  verb = get(GL_P_ITBL, K_P_VERB);
  if (verb == 0) {
    (await RT_NOT_IN_SENTENCE_MSG("any verbs"));
    return false;
  }
  syn = get(g.VERBS, 255 - verb);
  len = getb(syn, 0);
  syn = syn + 1;
  loop1: for (;;) {
    num = shift(getb(syn, 0), -6);
    if (s16(g.GL_P_NCN) > s16(num)) {
    } else if ((s16(num) >= s16(1)) && (g.GL_P_NCN == 0) && (((prep = get(GL_P_ITBL, K_P_PREP1)) == 0) || (prep == (await RT_GET_PREP(syn, 1))))) {
      drive1 = syn;
    } else if (eq(await RT_GET_PREP(syn, 1), get(GL_P_ITBL, K_P_PREP1))) {
      if ((num == 2) && (g.GL_P_NCN == 1)) {
        drive2 = syn;
      } else if ((s16(num) <= s16(1)) && !!(get(GL_P_ITBL, K_P_PREP2))) {
      } else if ((s16(num) <= s16(1)) || eq(await RT_GET_PREP(syn, 2), get(GL_P_ITBL, K_P_PREP2))) {
        await RT_SYNTAX_FOUND(syn);
        return true;
      }
    }
    if (--len < 1) {
      if (!(drive1 == 0) || !(drive2 == 0)) {
        break loop1;
      } else if ((g.GL_P_NCN == 2) && g.GL_FUNNY_CLAUSE$) {
        g.GL_P_NCN = 1;
        g.GL_FUNNY_CLAUSE$ = false;
        put(GL_P_ITBL, K_P_NC1L, get(GL_P_ITBL, K_P_NC2L));
        return await RT_SYNTAX_CHECK();
      } else {
        tell(S(K_DONT_UNDERSTAND_MSG), "\n");
        return false;
      }
    } else {
      if (num == 0) {
        syn = syn + K_P_SLEN_0;
      } else if (num == 1) {
        syn = syn + K_P_SLEN_1;
      } else {
        syn = syn + K_P_SLEN_2;
      }
    }
  }
  if (!(drive1 == 0) && (obj = await RT_GET_WHAT_I_MEAN(getb(drive1, K_P_SFWIM1), getb(drive1, K_P_SLOC1), await RT_GET_PREP(drive1, 1)))) {
    put(g.GL_P_PRSO, K_P_MATCHLEN, 1);
    put(g.GL_P_PRSO, 1, obj);
    await RT_SYNTAX_FOUND(drive1);
    return true;
  } else if (!(drive2 == 0) && (obj = await RT_GET_WHAT_I_MEAN(getb(drive2, K_P_SFWIM2), getb(drive2, K_P_SLOC2), await RT_GET_PREP(drive2, 2)))) {
    put(g.GL_P_PRSI, K_P_MATCHLEN, 1);
    put(g.GL_P_PRSI, 1, obj);
    await RT_SYNTAX_FOUND(drive2);
    return true;
  } else if (verb == ACT.FIND) {
    tell(S(K_DO_IT_YOURSELF_MSG), "\n");
    return false;
  } else {
    if (g.GL_WINNER == CH_PLAYER) {
      await RT_ORPHAN(drive1, drive2);
      tell("[Wh");
    } else {
      tell("[Your command was not complete. Type wh");
    }
    if (verb == ACT.WALK || verb == ACT.GO) {
      tell("ere");
    } else if ((!(drive1 == 0) && eq(getb(drive1, K_P_SFWIM1), FL_PERSON)) || (!(drive2 == 0) && eq(getb(drive2, K_P_SFWIM2), FL_PERSON))) {
      tell("om");
    } else {
      tell("at");
    }
    if (g.GL_WINNER == CH_PLAYER) {
      tell(" do you want to ");
    } else {
      tell(" you want ");
      await RT_THEO_PRINT(g.GL_WINNER);
      tell(" to ");
    }
    await RT_VERB_PRINT();
    if (!(drive2 == 0)) {
      await RT_CLAUSE_PRINT(K_P_NC1, K_P_NC1L);
    }
    g.GL_P_END_ON_PREP = false;
    await RT_PREP_PRINT(!(drive1 == 0) ? (await RT_GET_PREP(drive1, 1)) : (await RT_GET_PREP(drive2, 2)));
    if (g.GL_WINNER == CH_PLAYER) {
      g.GL_P_ORPH = true;
      tell("?]\n");
    } else {
      g.GL_P_ORPH = false;
      tell(".]\n");
    }
    return false;
  }
}

async function RT_CLAUSE(ptr, val, wrd) {
  let off = 0, num = 0, andflg = false, first$$ = true, nw = 0, lw = 0, tptr = 0, tmp = 0;
  off = (g.GL_P_NCN - 1) * 2;
  if (!(val == 0)) {
    put(GL_P_ITBL, num = K_P_PREP1 + off, val);
    put(GL_P_ITBL, num + 1, wrd);
    ptr = ptr + K_P_LEXELEN;
  } else {
    g.GL_P_LEN = g.GL_P_LEN + 1;
  }
  if (g.GL_P_LEN == 0) {
    g.GL_P_NCN = g.GL_P_NCN - 1;
    return -1;
  }
  put(GL_P_ITBL, num = K_P_NC1 + off, GL_P_P_LEX + (ptr * 2));
  if (eq(get(GL_P_P_LEX, ptr), W.THE, W.A, W.AN)) {
    put(GL_P_ITBL, num, get(GL_P_ITBL, num) + 4);
  }
  for (;;) {
    if (s16(g.GL_P_LEN = g.GL_P_LEN - 1) < s16(0)) {
      put(GL_P_ITBL, num + 1, GL_P_P_LEX + (ptr * 2));
      return -1;
    }
    if (!((wrd = get(GL_P_P_LEX, ptr)) == 0) || (wrd = await RT_NUMBER$(ptr))) {
      if (g.GL_P_LEN == 0) {
        nw = 0;
      } else {
        if (!(nw = get(GL_P_P_LEX, tptr = ptr + K_P_LEXELEN))) {
          if (wrd != W.INTNUM) {
            nw = await RT_NUMBER$(tptr);
            put(GL_P_P_LEX, tptr, nw);
          }
        }
      }
      if ((wrd == W.PERIOD) && ((lw == W.MR || lw == W.MRS || lw == W.MISS) || (lw == W.DR))) {
        lw = 0;
      } else if (wrd == W.AND || wrd == W.COMMA) {
        andflg = true;
      } else if (wrd == W.ALL || wrd == W.BOTH || wrd == W.EVERYTHING) {
        if (nw == W.OF) {
          g.GL_P_LEN = g.GL_P_LEN - 1;
          ptr = ptr + K_P_LEXELEN;
        }
      } else if ((wrd == W.THEN || wrd == W.PERIOD) || (btst(getb(wrd, 6), 8) && get(GL_P_ITBL, K_P_VERB) && !first$$)) {
        g.GL_P_LEN = g.GL_P_LEN + 1;
        put(GL_P_ITBL, num + 1, GL_P_P_LEX + (ptr * 2));
        return ptr - K_P_LEXELEN;
      } else if (!(andflg == 0) && ((get(GL_P_ITBL, K_P_VERBN) == 0) || (await RT_VERB_DIR_ONLY$(wrd)))) {
        ptr = ptr - 4;
        await RT_CHANGE_LEXV(ptr + 2, W.THEN);
        g.GL_P_LEN = g.GL_P_LEN + 2;
      } else if (btst(getb(wrd, 6), 128)) {
        if ((s16(g.GL_P_LEN) > s16(0)) && (nw == W.OF) && !(wrd == W.ALL || wrd == W.EVERYTHING)) {
          put(GL_P_OFW, g.GL_P_NCN - 1, wrd);
        } else if (btst(getb(wrd, 6), 32) && !(nw == 0) && btst(getb(nw, 6), 128)) {
          if ((wrd == W.INTNUM) && (nw == W.HOUR || nw == W.HOURS || nw == W.MINUTE || nw == W.MINUTES)) {
          } else if (nw == W.TOMB) {
          } else {
            if (wrd == W.BOX) {
              if (nw != W.INTNUM) {
                tmp = true;
              }
            } else if (wrd == W.TOMB) {
              tmp = true;
            }
            if (tmp) {
              g.GL_FUNNY_CLAUSE$ = true;
              put(GL_P_ITBL, num = num + 1, GL_P_P_LEX + ((ptr + 2) * 2));
              return ptr;
            }
          }
        } else if ((andflg == 0) && !(nw == W.BUT || nw == W.EXCEPT) && !(nw == W.AND || nw == W.COMMA)) {
          put(GL_P_ITBL, num + 1, GL_P_P_LEX + ((ptr + 2) * 2));
          return ptr;
        } else {
          andflg = false;
        }
      } else if ((!(g.GL_P_MERGED == 0) || !(g.GL_P_ORPH == 0) || !(get(GL_P_ITBL, K_P_VERB) == 0)) && !((getb(wrd, 6) & 36) == 0)) {
      } else if (!(andflg == 0) && (get(GL_P_ITBL, K_P_VERB) == 0)) {
        ptr = ptr - 4;
        await RT_CHANGE_LEXV(ptr + 2, W.THEN);
        g.GL_P_LEN = g.GL_P_LEN + 2;
      } else if (btst(getb(wrd, 6), 8)) {
      } else {
        await RT_DONT_KNOW_WORD_USE_MSG(ptr);
        return false;
      }
    } else {
      await RT_DONT_KNOW_WORD_MSG(ptr);
      return false;
    }
    lw = wrd;
    first$$ = false;
    ptr = ptr + K_P_LEXELEN;
  }
}

async function RT_GET_WHAT_I_MEAN(gbit, lbit, prep, no_rooms$ = false, silent$ = false) {
  let obj = 0;
  if (gbit == FL_LOCATION) {
    return ROOMS;
  } else if (!(g.GL_P_IT_OBJECT == 0) && hasFlag(g.GL_P_IT_OBJECT, gbit)) {
    if (!silent$) {
      tell("[");
      await RT_THEO_PRINT(g.GL_P_IT_OBJECT);
      tell("]\n");
    }
    return g.GL_P_IT_OBJECT;
  }
  g.INHIBIT_ROOMS = no_rooms$;
  g.GL_P_GWIMBIT = gbit;
  g.GL_P_SLOCBITS = lbit;
  put(g.GL_P_MERGE, K_P_MATCHLEN, 0);
  if (await RT_GET_OBJECT(g.GL_P_MERGE, false)) {
    g.GL_P_GWIMBIT = 0;
    if (eq(get(g.GL_P_MERGE, K_P_MATCHLEN), 1)) {
      obj = get(g.GL_P_MERGE, 1);
      if ((g.GL_WINNER == CH_PLAYER) && !(obj == TH_HANDS) && !silent$) {
        tell("[");
        if (await RT_PREP_PRINT(prep, false)) {
          printC(32);
        }
        await RT_THEO_PRINT(obj);
        tell("]\n");
      }
      g.INHIBIT_ROOMS = false;
      return obj;
    } else {
      return false;
    }
  } else {
    g.GL_P_GWIMBIT = 0;
    g.INHIBIT_ROOMS = false;
    return false;
  }
}

