        g.GL_WINNER = owinner;
        await RT_INBUF_ADD(getb(GL_P_P_LEX, (ptr * K_P_LEXELEN) + 6), getb(GL_P_P_LEX, (ptr * K_P_LEXELEN) + 7), (get(GL_OOPS_TABLE, K_O_PTR) * K_P_LEXELEN) + 3);
        await RT_STUFF(GL_P_P_LEX, GL_P_S_LEX);
