      put(GL_OOPS_TABLE, K_O_START, ptr);
      put(GL_OOPS_TABLE, K_O_LENGTH, 4 * g.GL_P_LEN);
      len = 2 * (ptr + (K_P_LEXELEN * getb(GL_P_P_LEX, K_P_LEXWORDS)));
