async function RT_DESC_PL_CONT_1(surface, cnt) {
  let obj = 0, nxt = 0, first_ = 0, person_count = 0, person_plural = false;
  obj = first(surface);
  first_ = true;
  loop1: for (;;) {
    if (obj == 0) {
      break loop1;
    } else if (hasFlag(obj, FL_NODESC) || (obj == g.GL_PUPPY)) {
      obj = next(obj);
      continue loop1;
    } else if (hasFlag(obj, FL_PERSON)) {
      person_count = person_count + 1;
      obj = next(obj);
      continue loop1;
    } else if (!(first_ == 0)) {
      if (s16(cnt) > s16(0)) {
        tell(" ");
      } else {
        crlf();
      }
      tell("You see ");
      first_ = false;
    }
    await RT_A_PRINT(obj);
    ++cnt;
    obj = next(obj);
    loop2: for (;;) {
      if (obj == 0) {
        break loop2;
      } else if ((obj == g.GL_PUPPY) || hasFlag(obj, FL_NODESC)) {
      } else if (hasFlag(obj, FL_PERSON) && !(hasFlag(obj, FL_NODESC))) {
        person_count = person_count + 1;
      } else {
        break loop2;
      }
      obj = next(obj);
    }
    if (!(obj == 0)) {
      nxt = next(obj);
      loop3: for (;;) {
        if (nxt == 0) {
          break loop3;
        } else if (!(hasFlag(nxt, FL_NODESC)) && !(nxt == g.GL_PUPPY) && !(hasFlag(nxt, FL_PERSON))) {
          break loop3;
        }
        nxt = next(nxt);
      }
      if (nxt == 0) {
        tell(" and ");
      } else {
        tell(", ");
      }
    } else {
      if (!(loc(surface) == ROOMS)) {
        tell(" on ");
        await RT_THEO_PRINT(surface);
      }
      tell(".");
    }
  }
  if (s16(person_count) > s16(0)) {
    if (s16(cnt) > s16(0)) {
      tell(" ");
    } else {
      crlf();
    }
    cnt = cnt + person_count;
    if (s16(person_count) > s16(1)) {
      person_plural = true;
    }
    obj = first(surface);
    first_ = true;
    loop4: for (;;) {
      if (hasFlag(obj, FL_NODESC) || (obj == g.GL_PUPPY)) {
      } else if (hasFlag(obj, FL_PERSON)) {
        if (first_) {
          await RT_THEO_PRINT(obj, true, K_DESC_A);
        } else {
          await RT_A_PRINT(obj);
        }
        first_ = false;
        if (hasFlag(obj, FL_PLURAL)) {
          person_plural = true;
        }
        if ((person_count = person_count - 1) == 0) {
          if (person_plural) {
            tell(" are");
          } else {
            tell(" is");
          }
          tell(" here.");
          break loop4;
        } else if (person_count == 1) {
          tell(" and ");
        } else {
          tell(", ");
        }
      }
      obj = next(obj);
    }
  }
  obj = first(surface);
  loop5: for (;;) {
    if (obj == 0) {
      break loop5;
    } else if (hasFlag(obj, FL_SURFACE)) {
      cnt = await RT_DESC_PL_CONT_1(obj, cnt);
    }
    obj = next(obj);
  }
  return cnt;
}

