async function RT_PARSE_EVENT$(noun, adj) {
  let obj = TH_EVENT, n_ = 0, tb = 0, ntb = 0, atb = 0, flgs = 0;
  n_ = div(get(TH_EVENT_NAMES, 0), EN_ENTLEN);
  tb = (TH_EVENT_NAMES + 2);
  ntb = 0;
  atb = 0;
  flgs = 0;
  for (;;) {
    if (inTable(noun, (ntb = get(tb, 0)) + 2, get(ntb, 0))) {
      if (!adj || ((atb = get(tb, 1)) && inTable(adj, atb + 2, get(atb, 0)))) {
        putProp(obj, P.OBJ_NOUN, get(ntb, 1));
        flgs = get(tb, 3);
        if (!!(flgs & EN_ALIVE)) {
          setFlag(obj, FL_ALIVE);
        } else {
          clearFlag(obj, FL_ALIVE);
        }
        if (!!(flgs & EN_PERSON)) {
          setFlag(obj, FL_PERSON);
        } else {
          clearFlag(obj, FL_PERSON);
        }
        if (!!(flgs & EN_VOWEL)) {
          setFlag(obj, FL_VOWEL);
        } else {
          clearFlag(obj, FL_VOWEL);
        }
        return obj;
      } else {
        return false;
      }
    }
    if (s16(n_ = n_ - 1) < s16(1)) {
      return false;
    }
    tb = tb + (EN_ENTLEN * 2);
  }
}

async function RT_IDENTIFY_EVENT$(wd, obj = false) {
  let nam = getProp(TH_EVENT, P.OBJ_NOUN), n_ = 0, tb = 0, ntb = 0;
  if (obj && (obj != TH_EVENT)) {
    return false;
  }
  n_ = div(get(TH_EVENT_NAMES, 0), EN_ENTLEN);
  tb = (TH_EVENT_NAMES + 2);
  ntb = 0;
  for (;;) {
    if (wd == get(ntb = get(tb, 0), 1)) {
      if (inTable(nam, ntb + 2, get(ntb, 0))) {
        return true;
      } else {
        return false;
      }
    }
    if (s16(n_ = n_ - 1) < s16(1)) {
      return false;
    }
    tb = tb + (EN_ENTLEN * 2);
  }
}

async function RT_DESC_EVENT(class_ = false) {
  let wd = getProp(TH_EVENT, P.OBJ_NOUN), flags = 0, n_ = 0, tb = 0;
  n_ = div(get(TH_EVENT_NAMES, 0), EN_ENTLEN);
  tb = (TH_EVENT_NAMES + 2);
  for (;;) {
    if (wd == get(get(tb, 0), 1)) {
      flags = get(tb, 3);
      if (get(tb, 2)) {
        await PRINT_SDESC(get(tb, 2), class_, !((flags & EN_NOARTC) == 0), hasFlag(TH_EVENT, FL_PLURAL), hasFlag(TH_EVENT, FL_VOWEL));
      } else {
        await PRINT_SDESC(wd, class_, !((flags & EN_NOARTC) == 0), hasFlag(TH_EVENT, FL_PLURAL), hasFlag(TH_EVENT, FL_VOWEL), true);
      }
      return true;
    }
    if (s16(n_ = n_ - 1) < s16(1)) {
      return false;
    }
    tb = tb + (EN_ENTLEN * 2);
  }
}

