async function RT_NUMBER$(ptr) {
  let tmp = 0, cnt = 0, bptr = 0, tptr = K_HRS, chr = 0, sum = 0, tim = false, am_pm$ = 0;
  tmp = GL_P_P_LEX + (ptr * 2);
  if (eq(cnt = get(tmp, K_P_LEXELEN), W.AM)) {
    am_pm$ = 1;
  } else if (cnt == W.PM) {
    am_pm$ = 2;
  }
  if (!!am_pm$) {
    g.BELIEVE_WAIT_TIME$ = true;
  } else {
    g.BELIEVE_WAIT_TIME$ = false;
  }
  cnt = getb(tmp, 2);
  bptr = getb(tmp, 3);
  loop1: for (;;) {
    if (--cnt < 0) {
      break loop1;
    } else {
      chr = getb(GL_P_PIBUF, bptr);
      if ((chr == 58 /* ":" */)) {
        putb(GL_P_TIME, tptr, sum);
        if (tptr == K_HRS) {
          if (s16(sum) > s16(23)) {
            return false;
          }
          if ((am_pm$ == 2) && (s16(sum) < s16(12))) {
            sum = sum + 12;
            putb(GL_P_TIME, K_HRS, sum);
          }
          tptr = K_MIN;
        } else if (tptr == K_MIN) {
          return false;
        } else if (tptr == K_SEC) {
          return false;
        }
        tim = true;
        sum = 0;
      } else if (s16(sum) > s16(9999)) {
        return false;
      } else if (((s16(chr) > s16(57 /* "9" */)) || (s16(chr) < s16(48 /* "0" */)))) {
        return false;
      } else {
        (sum = ((sum * 10) + (chr - 48 /* "0" */)));
      }
      bptr = bptr + 1;
    }
  }
  if (!(tim == 0)) {
    putb(GL_P_TIME, tptr, sum);
    if (tptr == K_HRS) {
      return false;
    } else if (tptr == K_MIN) {
      if ((s16(sum) < s16(0)) || (s16(sum) > s16(59))) {
        return false;
      }
    } else if (tptr == K_SEC) {
      return false;
    }
  } else {
    if ((am_pm$ == 2) && (s16(sum) < s16(12))) {
      sum = sum + 12;
    }
    putb(GL_P_TIME, K_HRS, sum);
    putb(GL_P_TIME, K_MIN, 0);
    putb(GL_P_TIME, K_SEC, 0);
  }
  await RT_CHANGE_LEXV(ptr, W.INTNUM);
  if (s16(sum) > s16(9999)) {
    return false;
  } else if (!(tim == 0)) {
    sum = 0;
  }
  g.GL_P_TIME_FLAG = tim;
  g.GL_P_NUMBER = sum;
  return W.INTNUM;
}

async function V_WAIT_FOR() {
  let h = 0, m = 0, s_ = 0, n_ = 0;
  if (g.GL_PRSO == TH_TIME) {
    n_ = g.GL_P_NUMBER;
    if (n_ == (-1)) {
      n_ = 1;
    }
    if (eq(getProp(g.GL_PRSO, P.OBJ_NOUN), W.MINUTE, W.MINUTES)) {
      h = 0;
      m = n_;
    } else {
      h = n_;
      m = 0;
    }
    s_ = 0;
    tell("Time passes...\n");
    return await RT_CLOCK_JMP(h, m, s_);
  } else if ((g.GL_P_TIME_FLAG == 0) && !(g.GL_PRSO == TH_INTNUM)) {
    await RT_CYOU_MSG();
    tell(S(K_CANT_WAIT_MSG), "\n");
    return M_FATAL;
  } else {
    h = getb(GL_P_TIME, K_HRS);
    m = getb(GL_P_TIME, K_MIN);
    s_ = getb(GL_P_TIME, K_SEC);
    if ((g.GL_PRSO == TH_INTNUM) && (g.GL_P_TIME_FLAG == 0)) {
      tell("[", N(h), ":00]\n\n");
    }
    if (s16(h) > s16(23)) {
      await RT_CYOU_MSG();
      tell(S(K_CANT_WAIT_MSG), "\n");
      return M_FATAL;
    } else if (g.BELIEVE_WAIT_TIME$ || (s16(h) > s16(12))) {
      h = h - getb(GL_TIME, K_HRS);
      m = m - getb(GL_TIME, K_MIN);
      s_ = s_ - getb(GL_TIME, K_SEC);
    } else {
      h = h - (mod(getb(GL_TIME, K_HRS) - 1, 12) + 1);
      m = m - getb(GL_TIME, K_MIN);
      s_ = s_ - getb(GL_TIME, K_SEC);
    }
    n_ = div(s_ - 59, 60);
    m = m + n_;
    s_ = s_ - (n_ * 60);
    n_ = div(m - 59, 60);
    h = h + n_;
    m = m - (n_ * 60);
    loop1: for (;;) {
      if (s16(h) >= s16(0)) {
        break loop1;
      }
      if (g.BELIEVE_WAIT_TIME$) {
        h = h + 24;
      } else {
        h = h + 12;
      }
    }
    if ((h == 0) && (m == 0) && (s_ == 0)) {
      tell("It is");
      if (s16(mod(getb(GL_TIME, K_HRS) - 1, 12) + 1) > s16(9)) {
        tell(" ");
      }
      await RT_CLK_NTI_MSG(K_NTI_HH | K_NTI_MM);
      tell(" now.\n");
      await RT_TIME_OF_DAY_MSG(true);
      return M_FATAL;
    } else {
      tell("Time passes...\n");
      await RT_CLOCK_JMP(h, m, s_);
      await RT_TIME_OF_DAY_MSG(true);
    }
    return true;
  }
}

