async function RT_WINDOW(table, margin = 0) {
  let y = 8, i = 2, width = 0, lines = 0, str = 0, plines = 0;
  lines = get(table, 0);
  width = get(table, 1);
  plines = lines;
  if (s16(width) > s16(g.GL_ALLSCREEN)) {
    tell("[*** Window too wide ***]\n");
    return true;
  }
  if (margin == 0) {
    margin = g.GL_MIDSCREEN - div(width, 2);
  }
  splitWindow(lines + 6);
  setWindow(K_S_WIN);
  highlight(K_H_INV);
  cursorSet(y, margin);
  await RT_PRINT_SPACES(width);
  loop1: for (;;) {
    ++y;
    cursorSet(y, margin);
    --lines;
    if (lines == 0) {
      await RT_PRINT_SPACES(width);
      break loop1;
    }
    str = get(table, i);
    if (str == 0) {
      await RT_PRINT_SPACES(width);
    } else {
      tell(" ", S(str), " ");
    }
    ++i;
  }
  highlight(K_H_NRM);
  setWindow(K_S_NOR);
  splitWindow(1);
  dirOut(K_D_SCR_OFF);
  i = 2;
  tell("\n[");
  loop2: for (;;) {
    --plines;
    if (plines == 0) {
      break loop2;
    }
    str = get(table, i);
    if (!(str == 0)) {
      if (!(i == 2)) {
        tell(" ");
      }
      tell(S(str));
      if (plines == 1) {
        tell("]");
      }
    }
    crlf();
    ++i;
  }
  crlf();
  dirOut(K_D_SCR_ON);
  return true;
}

