async function SOUNDS(n_, op = S_START, vol = 8, num = 1, rtn = 0) {
  if ((s16(g.LOOPING$) < s16(0)) && (op == S_START)) {
    g.LOOPING$ = 0;
    tell("\n[Use $SOUND to toggle sound usage on and off.]\n");
  }
  if ((op == S_INIT) && (g.SOUND_QUEUED$ || g.LOOPING$)) {
    return true;
  }
  if (n_ == S_CROWD) {
    vol = 6;
  } else if (n_ == S_BADVIOL) {
    vol = 6;
  }
  if (n_ == S_CROWD || n_ == S_BOATING || n_ == S_SNORE) {
    if (op == S_START) {
      g.LOOPING$ = n_;
      g.LOOP_VOL = vol;
      num = -1;
    } else if (op == S_STOP) {
      g.LOOPING$ = 0;
    }
    if (g.SOUND_QUEUED$) {
      return true;
    }
  } else {
    if (!rtn) {
      rtn = CHECK_LOOPING.id;
    }
  }
  if (g.SOUND_ON$) {
    if (op == S_START) {
      if (n_ != S_CROWD) {
        g.SOUND_QUEUED$ = n_;
      }
      sound(n_, op, shift(num, 8) | vol, rtn);
    } else {
      sound(n_, op);
    }
  }
  return true;
}

async function CHECK_LOOPING() {
  g.SOUND_QUEUED$ = false;
  if (s16(g.LOOPING$) > s16(0)) {
    await SOUNDS(g.LOOPING$, S_START, g.LOOP_VOL);
  }
  return true;
}

