async function V_HINT() {
  let chr = 0, maxc = 0, c_ = false, q = 0, who = false;
  restart: for (;;) {
    if (g.GL_HINTS_OFF) {
      await RT_PERFORM(V.HINTS_NO, ROOMS);
      return M_FATAL;
    } else if (!g.GL_HINT_WARNING) {
      g.GL_HINT_WARNING = true;
      tell("[Warning: It is recognized that the temptation for help may at times be so exceedingly strong that you might fetch hints prematurely. Therefore, you may at any time during the story type HINTS OFF, and this will disallow the seeking out of help for the present session of the story. If you still want a hint now, indicate HINT.]\n");
      return M_FATAL;
    } else if (!who) {
      who = await RT_WHO_SAYS$();
      if (who == CH_HOLMES || who == CH_WIGGINS) {
        if (who == CH_HOLMES) {
          tell("Holmes looks at you impatiently and sighs, \"Very well, Watson. If you must.\"");
        } else {
          tell("Wiggins looks up at you with relief and says, \"Good idea, guv. We'll never work this out on our own.\"");
        }
        tell("\n\n[Press any key to continue.]\n");
        await readChar(1);
      }
    }
    g.SOUND_QUEUED$ = false;
    await KILL_SOUNDS();
    maxc = get(K_HINTS, 0);
    await RT_INIT_HINT_SCREEN();
    cursorSet(5, 1);
    await RT_PUT_UP_CHAPTERS();
    g.GL_CUR_POS = g.GL_CHAPT_NUM - 1;
    await RT_NEW_CURSOR();
    loop1: for (;;) {
      chr = await readChar(1);
      if ((chr == 81 /* "Q" */ || chr == 113 /* "q" */)) {
        q = true;
        break loop1;
      } else if ((chr == 78 /* "N" */ || chr == 110 /* "n" */)) {
        await RT_ERASE_CURSOR();
        if (g.GL_CHAPT_NUM == maxc) {
          g.GL_CUR_POS = 0;
          g.GL_CHAPT_NUM = 1;
          g.GL_QUEST_NUM = 1;
        } else {
          g.GL_CUR_POS = g.GL_CUR_POS + 1;
          g.GL_CHAPT_NUM = g.GL_CHAPT_NUM + 1;
          g.GL_QUEST_NUM = 1;
        }
        await RT_NEW_CURSOR();
      } else if ((chr == 80 /* "P" */ || chr == 112 /* "p" */)) {
        await RT_ERASE_CURSOR();
        if (g.GL_CHAPT_NUM == 1) {
          g.GL_CHAPT_NUM = maxc;
          g.GL_CUR_POS = maxc - 1;
        } else {
          g.GL_CUR_POS = g.GL_CUR_POS - 1;
          g.GL_CHAPT_NUM = g.GL_CHAPT_NUM - 1;
        }
        g.GL_QUEST_NUM = 1;
        await RT_NEW_CURSOR();
      } else if (chr == 13 || chr == 10) {
        await RT_PICK_QUESTION();
        break loop1;
      }
    }
    if (!q) {
      continue restart;
    }
    clearScreen(-1);
    await V_REFRESH();
    who = await RT_WHO_SAYS$();
    if (who == CH_HOLMES) {
      tell("\nHolmes barely glances at you and snaps, \"At last. Now may we proceed?\"\n");
    } else if (who == CH_WIGGINS) {
      tell("\nWiggins tugs your sleeve and asks hopefully, \"Learn anything?\"\n");
    } else {
      tell("\nBack to the story...\n");
    }
    if (g.SOUND_ON$) {
      await CHECK_LOOPING();
    }
    return M_FATAL;
  }
}

