async function RT_DISPLAY_HINT() {
  let h = 0, mx = 0, cnt = 2, chr = 0, flg = true, n_ = 0, cv = 0, shift$ = 0, count_offs = 0, curcx = 0, curc = 0;
  clearScreen(-1);
  splitWindow(3);
  setWindow(K_S_WIN);
  cursorSet(1, 1);
  await RT_INVERSE_LINE();
  (await RT_CENTER_LINE(1, "INVISICLUES (tm)", 16));
  cursorSet(3, 1);
  await RT_INVERSE_LINE();
  (await RT_LEFT_LINE(3, "RETURN = see new hint"));
  (await RT_RIGHT_LINE(3, "Q = see hint menu", 17));
  cursorSet(2, 1);
  await RT_INVERSE_LINE();
  highlight(K_H_BLD);
  h = get(get(K_HINTS, g.GL_CHAPT_NUM), g.GL_QUEST_NUM + 1);
  cv = get(K_HINT_COUNTS, g.GL_CHAPT_NUM - 1);
  await RT_CENTER_LINE(2, get(h, 1));
  highlight(K_H_NRM);
  mx = get(h, 0);
  setWindow(K_S_NOR);
  crlf();
  shift$ = mod(g.GL_QUEST_NUM, 2);
  count_offs = div(g.GL_QUEST_NUM - 1, 2);
  curcx = getb(cv, count_offs);
  curc = (2 + ((shift$ ? shift(curcx, -4) : curcx) & 15));
  loop1: for (;;) {
    if (cnt == curc) {
      break loop1;
    } else {
      tell(S(get(h, cnt)), "\n");
      cnt = cnt + 1;
    }
  }
  for (;;) {
    if (flg && (s16(cnt) > s16(mx))) {
      flg = false;
      tell("[That's all.]\n");
    } else if (flg) {
      n_ = (mx - cnt) + 1;
      tell("[", N(n_), " hint");
      if (!(n_ == 1)) {
        tell("s");
      }
      tell(" left.] -> ");
      flg = false;
    }
    chr = await readChar(1);
    if ((chr == 81 /* "Q" */ || chr == 113 /* "q" */)) {
      if (shift$) {
        putb(cv, count_offs, (getb(cv, count_offs) & 15) | shift(cnt - 2, 4));
      } else {
        putb(cv, count_offs, (getb(cv, count_offs) & 240) | (cnt - 2));
      }
      return true;
    } else if (chr == 13 || chr == 10) {
      if (s16(cnt) <= s16(mx)) {
        flg = true;
        tell(S(get(h, cnt)), "\n");
        if (s16(cnt = cnt + 1) > s16(mx)) {
          flg = false;
          tell("[Final hint]\n");
        }
      }
    }
  }
}

