async function V_WAIT() {
  let h = 0, m = 0, s_ = 0, n_ = 0;
  if (g.GL_P_NUMBER == (-1)) {
    n_ = 1;
  } else {
    n_ = g.GL_P_NUMBER;
  }
  if (g.GL_PRSO == TH_TIME) {
    if (eq(getProp(g.GL_PRSO, P.OBJ_NOUN), W.MINUTE, W.MINUTES)) {
      h = 0;
      m = n_;
    } else {
      h = n_;
      m = 0;
    }
  } else if (g.GL_PRSO == TH_INTNUM) {
    h = 0;
    m = n_;
    tell("[", N(m), " minute");
    if (!(m == 1)) {
      tell("s");
    }
    tell("]\n\n");
  } else if (!(g.GL_PRSO == ROOMS)) {
    await RT_CYOU_MSG();
    tell("can't wait for that.\n");
    return true;
  } else {
    h = 0;
    m = 10;
  }
  s_ = 0;
  tell("Time passes...\n");
  await RT_CLOCK_JMP(h, m, s_);
  await RT_TIME_OF_DAY_MSG(true);
  return true;
}

async function V_WALK() {
  let pt = 0, pts = 0, str = 0, obj = 0, rm = 0;
  pt = getPropAddr(g.GL_PLACE_CUR, g.GL_PRSO);
  if (g.GL_P_WALK_DIR == 0) {
    tell("[You must specify a direction.]\n");
    return true;
  } else if (!(pt == 0)) {
    pts = propSize(pt);
    if (pts == K_UEXIT) {
      if (hasFlag(loc(g.GL_WINNER), FL_VEHICLE)) {
        await RT_PERFORM(V.EXIT, loc(g.GL_WINNER));
        if (hasFlag(loc(g.GL_WINNER), FL_VEHICLE)) {
          return M_FATAL;
        }
      }
      rm = getb(pt, K_REXIT);
      await RT_GOTO(rm);
      return true;
    } else if (pts == K_NEXIT) {
      str = get(pt, K_NEXITSTR);
      tell(S(str), "\n");
      return M_FATAL;
    } else if (pts == K_PEXIT) {
      rm = await apply(get(pt, K_PEXITRTN));
      if (!(rm == 0)) {
        await RT_GOTO(rm);
        return true;
      } else {
        return M_FATAL;
      }
    } else if (pts == K_CEXIT) {
      if (globalValue(getb(pt, K_CEXITFLG))) {
        rm = getb(pt, K_REXIT);
        await RT_GOTO(rm);
        return true;
      }
      await RT_CYOU_MSG();
      tell("cannot go that way.\n");
      return M_FATAL;
    } else if (pts == K_DEXIT) {
      if (hasFlag(loc(g.GL_WINNER), FL_VEHICLE)) {
        await RT_PERFORM(V.EXIT, loc(g.GL_WINNER));
        if (hasFlag(loc(g.GL_WINNER), FL_VEHICLE)) {
          return M_FATAL;
        }
      }
      obj = get(pt + 1, K_DEXITOBJ - 1);
      if (hasFlag(obj, FL_OPENED)) {
        rm = getb(pt, K_REXIT);
        await RT_GOTO(rm);
        return true;
      } else {
        tell("The door is not open.\n");
        return M_FATAL;
      }
    } else {
      return false;
    }
  } else if ((g.GL_P_WALK_DIR == P.OUT) && !(hasFlag(g.GL_PLACE_CUR, FL_INDOORS))) {
    (await RT_CYOU_MSG("are", "is"));
    tell("already outside.\n");
    return M_FATAL;
  } else if ((g.GL_P_WALK_DIR == P.IN) && hasFlag(g.GL_PLACE_CUR, FL_INDOORS)) {
    (await RT_CYOU_MSG("are", "is"));
    tell("already inside.\n");
    return M_FATAL;
  } else {
    tell("You cannot go that way.\n");
    return M_FATAL;
  }
}

