async function RT_QSR() {
  let key = 0;
  await KILL_SOUNDS();
  tell("The game is no longer afoot.\n\n");
  loop1: for (;;) {
    tell("Do you wish to: (1) Quit, (2) Restart, (3) Restore, (4) Hints");
    if (!(g.GL_CAN_UNDO == 0)) {
      tell(", (5) Undo");
    }
    tell(" ?\n");
    key = await readChar(1);
    if (key == 49) {
      await quit();
      tell("Quit failed.\n");
    } else if (key == 50) {
      await restart();
      tell("Restart failed.\n");
    } else if (key == 51) {
      if (!(g.GL_DEBUG_FLAG == 0)) {
        await V_REFRESH();
      }
      await RT_P_CLEAR();
      putb(GL_OOPS_INBUF, 1, 0);
      await restore();
      tell("Restore failed.\n");
    } else if (key == 52) {
      await V_HINT();
      await V_REFRESH();
      continue loop1;
    } else if ((key == 53) && !(g.GL_CAN_UNDO == 0)) {
      await V_UNDO();
    }
  }
}

