async function RT_GN_PAPER(tbl, len = 0) {
  let ptr = 0, obj = 0, paper = 0, cont = false, c_paper = false, held = false, h_paper = false, gnd = false, g_paper = false;
  if (len == 0) {
    len = get(tbl, 0);
  }
  ptr = tbl + 2;
  if (inTable(g.GL_P_IT_OBJECT, ptr, len)) {
    tell("[");
    await RT_CTHEO_PRINT(g.GL_P_IT_OBJECT);
    tell("]\n");
    return g.GL_P_IT_OBJECT;
  } else {
    loop1: for (;;) {
      if (s16(ptr) > s16(tbl + (len * 2))) {
        break loop1;
      } else {
        obj = get(ptr, 0);
      }
      if (hasFlag(loc(obj), FL_SURFACE)) {
        break loop1;
      } else if (eq(loc(obj), CH_PLAYER)) {
        if (held == 0) {
          held = true;
          h_paper = obj;
        } else {
          h_paper = false;
        }
      } else if (eq(loc(obj), g.GL_PLACE_CUR)) {
        if (gnd == 0) {
          gnd = true;
          g_paper = obj;
        } else {
          g_paper = false;
        }
      } else if ((cont == 0) && hasFlag(loc(obj), FL_CONTAINER)) {
        cont = loc(obj);
        c_paper = obj;
      } else if (hasFlag(loc(obj), FL_CONTAINER) && !(cont == 0) && !(eq(loc(obj), cont))) {
        c_paper = false;
      }
      ptr = ptr + 2;
    }
    if (!(obj == 0) && hasFlag(loc(obj), FL_SURFACE)) {
      paper = obj;
    } else if (!(h_paper == 0)) {
      paper = h_paper;
    } else if (!(g_paper == 0)) {
      paper = g_paper;
    } else if (!(c_paper == 0)) {
      paper = c_paper;
    } else {
      return false;
    }
    tell("[");
    await RT_CTHEO_PRINT(paper);
    tell("]\n\n");
    return paper;
  }
  return false;
}

