async function RT_AC_RM_221B_BAKER_ST(context = false) {
  if (!(await RT_DESCFCN_CONTEXT(context))) {
    if (!!context) {
      return false;
    } else {
      if (g.GL_PRSA == V.ENTER) {
        if (g.GL_PLACE_CUR == RM_ENTRY_HALL) {
          await RT_DO_WALK(P.EAST);
          return true;
        }
      }
      return false;
    }
  } else if (context == K_M_DESC_2) {
    if (g.GL_PLACE_PRV == RM_ENTRY_HALL) {
      tell("You emerge from the house into");
    } else {
      tell("You");
      await RT_DRIVE_WALK_MSG$();
      tell("into");
    }
    tell(" Baker Street.\n\n");
  }
  if (context == K_M_DESC_1 || context == K_M_DESC_2 || context == K_M_DESC_3) {
    tell("You are");
    await RT_IN_VEHICLE_MSG();
    if (eq(await RT_TIME_OF_DAY(), 0, 1, 3)) {
      tell("in the spill of a gas streetlight ");
    }
    tell("outside Holmes's house. The street ");
    if (eq(await RT_TIME_OF_DAY(), 0)) {
      tell("disappears into the fog");
    } else {
      tell("continues");
    }
    tell(" to the north and south. The door to the house is to the west.\n");
  }
  if (context == K_M_DESC_1) {
    setFlag(LG_BAKER_ST_DOOR, FL_SEEN);
    setFlag(CH_PLAYER, FL_SEEN);
    tell("\nYou have come in response to an urgent summons from your old landlady, Mrs Hudson. As the fog swirls around you, you huddle into your coat and shiver in the predawn chill.\n");
    return true;
  } else if (context == K_M_DESC_3 || context == K_M_DESC_2) {
    if (loc(CH_HOLMES) == RM_221B_BAKER_ST) {
      if (g.GL_PUPPY == 0) {
        tell("\n");
        await RT_CTHEO_PRINT(CH_HOLMES);
        tell(" says, \"Ah, there you are Watson. While you were inside I gave our little problem some thought. Obviously the person who stole the Crown Jewels wanted the authorities to turn to me for help, and it is equally obvious that the thief has laid down a trail for me to follow, in hopes of somehow entrapping me.\n\n\"So let's play his game, Doctor. But let's play it by our rules. The thief will have tried to anticipate the sequence of my actions, and I'm sure he has laid his trap accordingly. But if ");
        highlight(K_H_ITL);
        tell("you");
        highlight(K_H_NRM);
        tell(" were to guide the course of our investigations, he will certainly be thrown off the scent.\n\n\"Therefore, let us take surprise onto our side and rely on your instincts as the man of action I know you to be - despite your frequent modest assertions to the contrary.\" He steps to one side and says, \"Lead on, good Doctor. I will follow.\" Holmes gestures for you to lead the way.\n");
        g.GL_PUPPY = CH_HOLMES;
        g.GL_PUPPY_MSG$ = false;
        return true;
      } else {
        return false;
      }
    } else {
      return false;
    }
  } else if (context == K_M_DESC_2 || context == K_M_DESC_3) {
    return false;
  } else {
    return false;
  }
}

