async function RT_AC_RM_BANK_VAULT(context = false) {
  if (!(await RT_DESCFCN_CONTEXT(context))) {
    if (context == K_M_DESCFCN) {
      if (g.GL_PLACE_CUR == RM_BANK_OF_ENGLAND) {
        if (hasFlag(LG_BANK_VAULT_DOOR, FL_OPENED)) {
          await RT_AC_RM_BANK_VAULT(K_M_DESC_3);
          await RT_DESCRIBE_PLACE_CONTENTS(RM_BANK_VAULT);
          return true;
        } else {
          tell("It's a huge, reinforced-steel door that's set firmly into the wall.\n\nIn the middle of the door you see a big shiny dial.\n");
          return true;
        }
      } else {
        await RT_AC_RM_BANK_VAULT(K_M_DESC_3);
        await RT_DESCRIBE_PLACE_CONTENTS(RM_BANK_VAULT);
        return true;
      }
    } else if (!!context) {
      return false;
    } else if (g.GL_NOW_PRSI$ == 0) {
      if (g.GL_PRSA == V.ENTER) {
        if (g.GL_PLACE_CUR == RM_BANK_OF_ENGLAND) {
          await RT_DO_WALK(P.WEST);
          return true;
        }
      } else if (g.GL_PRSA == V.EXIT) {
        if (g.GL_PLACE_CUR == RM_BANK_VAULT) {
          await RT_DO_WALK(P.EAST);
          return true;
        }
      } else if (g.GL_PRSA == V.LOOK_INSIDE || g.GL_PRSA == V.SEARCH) {
        if (hasFlag(LG_BANK_VAULT_DOOR, FL_OPENED)) {
          (await RT_CYOU_MSG("see", "sees"));
          tell("row upon row of ");
          await DPRINT(TH_BOXES);
          tell(".\n");
          return true;
        } else {
          await RT_CTHEO_PRINT(LG_BANK_VAULT_DOOR);
          tell(" is closed.\n");
          return true;
        }
      } else if (g.GL_PRSA == V.UNLOCK) {
        if (hasFlag(LG_BANK_VAULT_DOOR, FL_OPENED)) {
          await RT_CTHEO_PRINT(LG_BANK_VAULT_DOOR);
          tell(" is already opened.\n");
        } else {
          tell(S(K_HOW_TO_MSG), "\n");
        }
        return true;
      } else if (g.GL_PRSA == V.OPEN) {
        if (hasFlag(LG_BANK_VAULT_DOOR, FL_OPENED)) {
          tell("The vault door is already open.\n");
          return true;
        } else if (hasFlag(TH_DIAL, FL_LOCKED)) {
          tell("The vault door is locked.\n");
          return true;
        } else {
          setFlag(LG_BANK_VAULT_DOOR, FL_OPENED);
          tell("The vault door swings open.\n");
          return true;
        }
      } else if (g.GL_PRSA == V.SHOOT) {
        tell(S(K_RICOCHET_MSG), "\n");
        return true;
      }
    }
    return false;
  } else if (context == K_M_DESC_1) {
    setFlag(TH_BOXES, FL_SEEN);
    setFlag(TH_BOX_LOCK, FL_SEEN);
    setFlag(TH_SAFETY_DEPOSIT_BOX, FL_SEEN);
  }
  if (context == K_M_DESC_1 || context == K_M_DESC_2) {
    tell("Upon entering, you");
  } else {
    tell("You");
  }
  tell(" see rows and rows of safety deposit boxes.\n");
  return false;
}

