async function PRINT_SDESC(base, class_, noart$, plural$, vowel$ = false, printb$ = false) {
  let is = false;
  if (!noart$) {
    if (class_ == K_DESC_ANY) {
      (is = "any");
    } else if ((class_ == K_DESC_THE) || plural$) {
      (is = "the");
    } else if (plural$) {
      (is = "some");
    } else {
      if (vowel$) {
        (is = "an");
      } else {
        (is = "a");
      }
    }
    if (is) {
      tell(S(is));
    }
    printC(32 /* " " */);
  }
  if (printb$) {
    return printB(base);
  } else {
    tell(S(base));
    return true;
  }
}

