async function RT_AC_TH_LAMP(context = false) {
  if (context == K_M_DESCFCN) {
    tell("It is a battered old brass lamp that has accompanied you on many adventures in the past.\n");
    return true;
  } else if (!(context == 0)) {
    return false;
  } else if (!(g.GL_NOW_PRSI$ == 0)) {
    if (g.GL_PRSA == V.THROW) {
      if (s16(await GET_MASS(g.GL_PRSO)) > s16(5)) {
        await RT_BREAK_LAMP();
        tell("\n");
        await RT_CTHEO_PRINT();
        tell(" ");
        await RT_LANDS_AT_YOUR_FEET_MSG();
        return true;
      } else {
        return false;
      }
    } else if (g.GL_PRSA == V.PUT) {
      return await RT_LAMP_SEALED();
    } else {
      return false;
    }
  } else {
    if (g.GL_PRSA == V.SHOOT || g.GL_PRSA == V.KICK || g.GL_PRSA == V.MUNG) {
      return await RT_BREAK_LAMP();
    } else if (g.GL_PRSA == V.OPEN || g.GL_PRSA == V.CLOSE || g.GL_PRSA == V.OPEN_WITH || g.GL_PRSA == V.LOOK_INSIDE || g.GL_PRSA == V.SEARCH || g.GL_PRSA == V.REACH_IN || g.GL_PRSA == V.EMPTY || g.GL_PRSA == V.EMPTY_INTO) {
      return await RT_LAMP_SEALED();
    } else if (g.GL_PRSA == V.LAMP_ON || g.GL_PRSA == V.LIGHT_WITH || g.GL_PRSA == V.TURN_UP || g.GL_PRSA == V.LIGHT) {
      if (hasFlag(TH_LAMP, FL_BROKEN)) {
        clearFlag(TH_LAMP, FL_ASLEEP);
        tell("Nothing happens.\n");
        return true;
      } else if (!(hasFlag(TH_LAMP, FL_ASLEEP))) {
        await RT_CTHEO_PRINT(TH_LAMP);
        tell(" is already on.\n");
        return true;
      } else {
        clearFlag(TH_LAMP, FL_ASLEEP);
        setFlag(TH_LAMP, FL_LIGHTED);
        tell("You turn up the wick. ");
        await RT_CTHEO_PRINT(TH_LAMP);
        tell(" emits a warm glow that lights up the area around you.\n");
        return true;
      }
    } else if (g.GL_PRSA == V.LAMP_OFF || g.GL_PRSA == V.TURN_DOWN) {
      if (hasFlag(TH_LAMP, FL_ASLEEP)) {
        await RT_CTHEO_PRINT(TH_LAMP);
        tell(" is already off.\n");
        return true;
      } else if (hasFlag(TH_LAMP, FL_BROKEN)) {
        setFlag(TH_LAMP, FL_ASLEEP);
        tell("Nothing happens.\n");
        return true;
      } else {
        setFlag(TH_LAMP, FL_ASLEEP);
        clearFlag(TH_LAMP, FL_LIGHTED);
        tell("You turn down the wick. ");
        await RT_CTHEO_PRINT(TH_LAMP);
        tell(" goes dark.\n");
        return true;
      }
    } else if (g.GL_PRSA == V.POINT_AT || g.GL_PRSA == V.SHINE_AT) {
      if (hasFlag(TH_LAMP, FL_LIGHTED)) {
        if (g.GL_PRSO == g.GL_PRSI) {
          await RT_CYOU_MSG();
          tell("can't point the light at itself.\n");
          return true;
        } else {
          tell("You point ");
          await RT_THEO_PRINT(TH_LAMP);
          tell(" at ");
          await RT_THEI_PRINT();
          tell(", but it reveals nothing.\n");
          return true;
        }
      } else {
        await RT_CTHEO_PRINT(TH_LAMP);
        tell(" is not on.\n");
        return true;
      }
    } else {
      return false;
    }
  }
}

