async function RT_AC_TH_BOAT(context = false) {
  let num = 0;
  if (context == K_M_DESCFCN) {
    tell("It's an incredibly old rowboat that ");
    if ((loc(TH_OAR_1) == TH_BOAT) && !(loc(TH_OAR_2) == TH_OAR_LOCK)) {
      tell("has one empty oarlock and ");
    }
    tell("probably leaks. But it looks as if it might float");
    if (!((loc(TH_BOAT) == RM_THE_EMBANKMENT) || (loc(TH_BOAT) == RM_OUTSIDE_TRAITORS_GATE))) {
      tell(" a little while longer");
    }
    tell(". The boat's anchor is in the ");
    if (loc(TH_ANCHOR) == TH_BOAT) {
      tell("boat");
    } else {
      tell("water");
    }
    tell(".\n");
    return 2;
  } else if (!(context == 0)) {
    return false;
  } else if ((g.GL_PRSA == V.PUSH_TO) && (g.GL_PRSI == LG_WATER)) {
    await RT_LAUNCH_BOAT();
    return true;
  } else if ((g.GL_PRSA == V.ENTER) && (g.GL_PRSO == ROOMS || g.GL_PRSO == TH_BOAT)) {
    if (!(loc(CH_PLAYER) == TH_BOAT)) {
      if (!(g.GL_PUPPY == 0) && (g.GL_WINNER == CH_PLAYER)) {
        move(g.GL_PUPPY, TH_BOAT);
        tell("You and ");
        await RT_THEO_PRINT(g.GL_PUPPY);
        tell(" get ");
      } else {
        (await RT_CYOU_MSG("get", "gets"));
      }
      tell("into the boat.\n");
      move(CH_PLAYER, TH_BOAT);
      if (!(g.GL_PUPPY == 0)) {
        move(g.GL_PUPPY, TH_BOAT);
      }
      setFlag(TH_BOAT, FL_NODESC);
      return true;
    } else {
      return false;
    }
  } else if ((g.GL_PRSA == V.EXIT) && (g.GL_PRSO == ROOMS || g.GL_PRSO == TH_BOAT)) {
    if (loc(CH_PLAYER) == TH_BOAT) {
      move(CH_PLAYER, g.GL_PLACE_CUR);
      if (!(g.GL_PUPPY == 0)) {
        move(g.GL_PUPPY, g.GL_PLACE_CUR);
      }
      clearFlag(TH_BOAT, FL_NODESC);
      num = g.TH_BOAT_AUX1;
      if (!(loc(TH_OPAL) == 0) && (loc(TH_BOAT) == RM_THE_EMBANKMENT) && (num == 0)) {
        tell("As");
        if (!(g.GL_PUPPY == 0) && (g.GL_WINNER == CH_PLAYER)) {
          move(g.GL_PUPPY, g.GL_PLACE_CUR);
          tell(" you and ");
          await RT_THEO_PRINT(g.GL_PUPPY);
          tell(" get ");
        } else {
          (await RT_YOU_MSG("get", "gets"));
        }
        tell("out of the boat, a man storms up to you and says, \"What in bloody 'ell are you doing with my boat?\" Without waiting for a reply he ");
        if ((loc(TH_OAR_2) == TH_BOAT) || (loc(TH_OAR_2) == RM_THE_EMBANKMENT) || (await RT_META_IN$(TH_OAR_2, CH_PLAYER)) || (await RT_META_IN$(TH_OAR_2, g.GL_PUPPY))) {
          tell("grabs the oar, ");
        }
        move(TH_BOAT, RM_OUTSIDE_TRAITORS_GATE);
        move(TH_ANCHOR, LG_WATER);
        remove(TH_OAR_1);
        remove(TH_OAR_2);
        g.TH_BOAT_AUX1 = 1;
        tell("jumps into the boat and rows off, muttering to himself that he'll have to find a safer place to keep it.\n");
      } else if (hasFlag(TH_GARNET, FL_TOUCHED) && (loc(TH_BOAT) == RM_THE_EMBANKMENT) && (num == 1)) {
        tell("As");
        if (!(g.GL_PUPPY == 0) && (g.GL_WINNER == CH_PLAYER)) {
          move(g.GL_PUPPY, g.GL_PLACE_CUR);
          tell(" you and ");
          await RT_THEO_PRINT(g.GL_PUPPY);
          tell(" get ");
        } else {
          (await RT_YOU_MSG("get", "gets"));
        }
        tell("out of the boat, its red-faced owner runs up and yells, \"You again?!!\" He gives you a swift kick in the rear");
        if (hasFlag(TH_SUIT_OF_ARMOUR, FL_WORN)) {
          tell(", then clutches his foot in agony as it bounces off your suit of armour");
        }
        tell(".\n\nThe man jumps into the boat");
        if (loc(TH_PADDLE) == TH_BOAT) {
          tell(" and paddles away, cursing under his breath.\n");
        } else {
          tell(", launches it, and suddenly realizes he has no way to steer it. The last you see of him, he is drifting down the Thames, screaming and shaking his fist at you.\n");
        }
        remove(TH_BOAT);
        g.TH_BOAT_AUX1 = 2;
      } else if (loc(TH_ANCHOR) == TH_BOAT) {
        tell("As");
        if (!(g.GL_PUPPY == 0) && (g.GL_WINNER == CH_PLAYER)) {
          move(g.GL_PUPPY, g.GL_PLACE_CUR);
          tell(" you and ");
          await RT_THEO_PRINT(g.GL_PUPPY);
          tell(" get ");
        } else {
          (await RT_YOU_MSG("get", "gets"));
        }
        tell("out of the boat it slides out from under your foot and drifts down the river.\n");
        remove(TH_BOAT);
      } else {
        if (!(g.GL_PUPPY == 0) && (g.GL_WINNER == CH_PLAYER)) {
          move(g.GL_PUPPY, g.GL_PLACE_CUR);
          tell("You and ");
          await RT_THEO_PRINT(g.GL_PUPPY);
          tell(" get ");
        } else {
          (await RT_CYOU_MSG("get", "gets"));
        }
        tell("out of the boat.\n");
      }
      return true;
    } else {
      return false;
    }
  } else if ((g.GL_PRSA == V.SHOOT) && (g.GL_PRSO == TH_BOAT)) {
    remove(TH_BOAT);
    tell("Bad idea. The bullet blows a hole in the boat, which promptly sinks.\n");
    if (loc(CH_PLAYER) == TH_BOAT) {
      tell("\nUnable to swim, you cling to a piece of driftwood for several hours, wondering what kind of idiot would shoot a boat out from under himself.\n\nAfter a while, a Scotland Yard launch pulls alongside to rescue you. Lestrade leans over the side and offers his assistance. You decide you're better off in the water and politely decline.\n\n");
      await RT_QSR();
    }
    return true;
  } else {
    return false;
  }
}

