async function RT_AC_TH_ETHERIUM_AMPOULE(context = false) {
  if (context == K_M_SDESC) {
    if (hasFlag(TH_ETHERIUM_AMPOULE, FL_BROKEN)) {
      tell("broken ampoule");
    } else {
      tell("ampoule of etherium");
    }
    return true;
  } else if (!(context == 0)) {
    return false;
  }
  if (hasFlag(TH_ETHERIUM_AMPOULE, FL_BROKEN)) {
    return await RT_AC_TH_BROKEN_AMPOULE();
  } else if ((g.GL_PRSA == V.MUNG || g.GL_PRSA == V.OPEN) && (g.GL_NOW_PRSI$ == 0)) {
    if (!(loc(TH_ETHERIUM_AMPOULE) == g.GL_WINNER)) {
      await RT_CYOU_MSG();
      (await RT_WOULD_HAVE_TO_MSG("be holding", g.GL_PRSO));
      tell(" to do that.\n");
      return M_FATAL;
    }
    if (hasFlag(g.GL_PLACE_CUR, FL_NO_ETHERIUM)) {
      if (eq(await RT_WHO_SAYS$(), CH_HOLMES)) {
        tell("Holmes stops you. \"Do try to be discreet, old boy. My research is supposed to be kept secret.\"\n");
        return M_FATAL;
      }
      tell("The etherium renders everyone quite unconscious. Unfortunately, word of the unusual phenomenon soon leaks out, the existence of the secret chemical is exposed, and you are arrested for violating the Official Secrets Act.\n\nBecause he thinks you are a traitor, even Lestrade refuses to visit you in prison. His absence is the only bright spot of your twenty-year incarceration.\n");
      await RT_QSR();
      return M_FATAL;
    } else if (!(g.GL_PLACE_CUR == RM_LAIR) && eq(await RT_WHO_SAYS$(), CH_HOLMES) && (g.GL_PLACE_CUR != RM_BAR_OF_GOLD) && !((g.GL_PLACE_CUR == RM_ENTRY_HALL || g.GL_PLACE_CUR == RM_HOLMES_STUDY || g.GL_PLACE_CUR == RM_EVANGELIST_CHAPEL) || (await RT_FIND_FLAME(g.GL_PLACE_CUR)))) {
      tell("Holmes stops you just in time. \"This is neither the time nor the place for experimentation.\"\n");
      return true;
    }
    await CLEAR_ALL_FLAGS(TH_ETHERIUM_AMPOULE);
    setFlag(TH_ETHERIUM_AMPOULE, FL_TAKEABLE);
    setFlag(TH_ETHERIUM_AMPOULE, FL_READABLE);
    setFlag(TH_ETHERIUM_AMPOULE, FL_BROKEN);
    put(getPropAddr(TH_ETHERIUM_AMPOULE, P.ADJECTIVE), 0, W.BROKEN);
    tell("You break open the ampoule.");
    if (g.GL_PLACE_CUR == RM_BAR_OF_GOLD) {
      tell(" The etherium fumes mix with the heavy air of the opium den. No one seems to notice.\n");
    } else if (hasFlag(g.GL_PLACE_CUR, FL_INDOORS)) {
      if ((await RT_FIND_FLAME(g.GL_PLACE_CUR)) || (g.GL_PLACE_CUR == RM_ENTRY_HALL || g.GL_PLACE_CUR == RM_HOLMES_STUDY || g.GL_PLACE_CUR == RM_EVANGELIST_CHAPEL)) {
        tell(" As soon as the volatile etherium comes in contact with the flame");
        if (g.GL_PLACE_CUR == RM_ENTRY_HALL) {
          tell(" of the gas light");
        } else if (g.GL_PLACE_CUR == RM_HOLMES_STUDY) {
          tell(" of the fireplace");
        } else if (g.GL_PLACE_CUR == RM_EVANGELIST_CHAPEL) {
          tell(" of the candles");
        }
        tell(", it explodes.\n\nB  O  O  M  !!!\n\nYou awaken several days later in the hospital. Inspector Lestrade is there with flowers for your bedside table. He is full of news about how he plans to solve the case. Upon hearing this, you lapse back into a coma from which you have no particular desire to emerge.\n");
        await RT_QSR();
      } else {
        tell(" The etherium is released into the room.");
        if (!(hasFlag(TH_BREATH, FL_LOCKED))) {
          setFlag(CH_PLAYER, FL_ASLEEP);
          tell(" Suddenly, everything starts to spin. You pass out and fall to the ground. Sometime later you awaken and stumble back to your feet.\n");
          await RT_CLOCK_JMP(6, 0, 0);
          if (g.GL_PLACE_CUR == RM_LAIR) {
            await RT_DOES_MORIARTY_WIN();
          }
        } else {
          if (await RT_ETHERIUM_EFFECT(true)) {
            tell(" You see everyone");
            if (await RT_VISIBLE$(CH_HOLMES)) {
              tell(" but Holmes");
            }
            tell(" pass out.");
          }
          crlf();
        }
        move(TH_ETHERIUM_GAS, g.GL_PLACE_CUR);
        await RT_ALARM_SET_REL(RT_I_WAKE_UP.id, await RT_DO_CLOCK_SET(GL_TIME_PARM, 6, 0, 0));
      }
    } else {
      tell(" The etherium fumes dissipate quickly.\n");
    }
    return true;
  } else if ((g.GL_NOW_PRSI$ == 0) && ((g.GL_PRSA == V.SHOOT) || ((g.GL_PRSA == V.BURN_WITH) && (!g.GL_PRSI || (hasFlag(g.GL_PRSI, FL_BURNABLE) && hasFlag(g.GL_PRSI, FL_LIGHTED)))))) {
    if (g.GL_PRSA == V.SHOOT) {
      tell("Couldn't resist it, could you?");
    }
    tell("\n\nB  O  O  M  !!!\n\nYour nerves - already fragile from the Afghan campaign - snap like a dry twig. You collapse into a babbling pile of jello, and white-coated attendants take you away to a nice sunlit room where Lestrade visits on alternate Tuesdays.\n");
    return await RT_QSR();
  } else if ((g.GL_PRSA == V.READ || g.GL_PRSA == V.EXAMINE || g.GL_PRSA == V.LOOK_ON) && (g.GL_NOW_PRSI$ == 0)) {
    tell("The label on the ampoule reads, \"Etherium. Extremely volatile. Do not open in the presence of fire.\"\n");
    return true;
  } else {
    return false;
  }
}

