async function RT_GET_ROOM_ID(here) {
  let tbl = 0;
  if (tbl = inTable(here, CAB_ROOM_IDS, CAB_ROOM_IDS_LEN, 1)) {
    if (s16(CAB_ROOM_IDS) < s16(0)) {
      return (tbl - CAB_ROOM_IDS) + 1;
    } else {
      return (CAB_ROOM_IDS - tbl) + 1;
    }
  } else {
    return 0;
  }
}

async function RT_CAB_DIST(here, there) {
  let num1 = 0, num2 = 0, ptr = 0, tmp = 0;
  num1 = await RT_GET_ROOM_ID(here);
  num2 = await RT_GET_ROOM_ID(there);
  if ((here == there) || (num1 == num2)) {
    return 0;
  }
  if (s16(num1) < s16(num2)) {
    tmp = num1;
    num1 = num2;
    num2 = tmp;
  }
  num1 = num1 - 2;
  loop1: for (;;) {
    if (s16(num1) < s16(1)) {
      break loop1;
    } else {
      ptr = ptr + num1;
      --num1;
    }
  }
  ptr = ptr + (num2 - 1);
  return getb(GL_CAB_DIST_TBL, ptr);
}

async function RT_I_CAB_ARRIVE() {
  let cab = false, place = false, num = 0, score = 0, aux1 = 0;
  num = g.TH_CAB_WHISTLE_AUX1;
  place = g.TH_CAB_WHISTLE_AUX2;
  g.TH_CAB_WHISTLE_AUX1 = 0;
  g.TH_CAB_WHISTLE_AUX2 = 0;
  if ((g.GL_PLACE_CUR == place) && !(g.GL_PRSA == V.WALK)) {
    if (num == 1) {
      cab = TH_GROWLER_CAB;
      score = 0;
      await RT_ALARM_SET_REL(RT_I_GROWLER_LEAVE.id, await RT_DO_CLOCK_SET(GL_TIME_PARM, 0, 5, 0));
      await RT_REMOVE_ALL(TH_GROWLER_CAB);
      move(CH_GROWLER_CABBIE, TH_GROWLER_CAB);
      setFlag(CH_GROWLER_CABBIE, FL_SEEN);
    } else if (num == 2) {
      cab = TH_HANSOM_CAB;
      score = 5;
      await RT_ALARM_SET_REL(RT_I_HANSOM_LEAVE.id, await RT_DO_CLOCK_SET(GL_TIME_PARM, 0, 5, 0));
      await RT_REMOVE_ALL(TH_HANSOM_CAB);
      move(CH_HANSOM_CABBIE, TH_HANSOM_CAB);
      setFlag(CH_HANSOM_CABBIE, FL_SEEN);
    } else {
      return false;
    }
    if (!g.SOUND_QUEUED$) {
      g.CAB_RAMP = 2;
      await RT_S_CAB_ARRIVES();
    }
    tell("\nA ");
    await DPRINT(cab);
    tell(" pulls up beside you.\n");
    move(cab, g.GL_PLACE_CUR);
    if (cab == TH_HANSOM_CAB) {
      aux1 = g.TH_HANSOM_CAB_AUX1;
    } else {
      aux1 = g.TH_GROWLER_CAB_AUX1;
    }
    if (aux1 == 0) {
      if (cab == TH_HANSOM_CAB) {
        g.TH_HANSOM_CAB_AUX1 = 1;
      } else {
        g.TH_GROWLER_CAB_AUX1 = 1;
      }
      if (!(score == 0)) {
        await RT_UPDATE_SCORE(score);
      }
    }
    return true;
  } else {
    return false;
  }
}

