async function RT_HOLE$(obj) {
  let off = 0, cnt = 0, num = 0, place = 0;
  loop1: for (;;) {
    off = num * 2;
    if (num == get(GL_HOLES, 0)) {
      break loop1;
    } else if (obj == get(GL_HOLES, off + 1)) {
      if (((place = get(GL_HOLES, off + 2)) == 0) || (g.GL_PLACE_CUR == place)) {
        ++cnt;
      }
    }
    ++num;
  }
  return cnt;
}

