    setFlag(CH_PRIME_MINISTER, FL_SEEN);
    await RT_ALARM_SET_REL(RT_I_PM_LEAVE.id, await RT_DO_CLOCK_SET(GL_TIME_PARM, 0, 3, 0));
    if ((g.GL_PLACE_CUR == RM_HOLMES_STUDY) && (num == 0)) {
      tell("\nMrs Hudson appears at the door, accompanied by a worried-looking gentleman.\n\nHolmes jumps up and ushers the gentleman to the armchair, dismissing Mrs Hudson at the same time. \"Watson,\" he says, \"I am sure you recognize our distinguished visitor. ");
    } else if ((g.GL_PLACE_CUR == RM_HOLMES_STUDY) && (num == 1 || num == 2)) {
      tell("\nHolmes has seated his visitor and is exchanging pleasantries with him. As you walk in Holmes looks up and says, \"Ah, here you are Watson. Now we can get down to business.\" He turns to the gentleman seated in the armchair and says, \"");
    } else {
      tell("\nHolmes appears and says, \"Come with me, Watson. We have an important visitor.\" He takes you by the arm and ushers you back to his study. Once inside, he gestures to the guest seated in the armchair and says, \"");
      move(CH_PLAYER, RM_HOLMES_STUDY);
      g.GL_PLACE_PRV = g.GL_PLACE_CUR;
      g.GL_PLACE_CUR = RM_HOLMES_STUDY;
    }
    tell("I presume, sir, that you have come about the Jewels.\"\n\nThe visitor half rises from his chair in protest and sputters, \"But...but, how...?\"\n\nHolmes calms him with a glance. \"Come, sir. What else could it be? The Tower is suddenly closed, and within hours I receive a call from the highest official of Her Majesty's government. A simple deduction. Now then, tell me about the theft.\"\n\nThe visitor settles back into his chair and says, \"We know very little. Only that the Crown Jewels were stolen from the Tower sometime Thursday night. The theft was discovered Friday morning, and we immediately closed and searched the Tower. All we found was this verse which was left behind in the empty jewel case.\"\n\nThe visitor removes a folded piece of paper from his pocket and gives it to Holmes, who glances at it and passes it on to you.\n");
    await RT_THIS_IS_IT(TH_WESTMINSTER_CLUE);
