async function RT_I_BIGBEN() {
  let hrs = 0, min = 0, sec = 0, yrs = 0, mon = 0, day = 0, ret = false;
  if (hasFlag(CH_PLAYER, FL_ASLEEP)) {
    return false;
  }
  if (!(g.GL_WAIT_BELL == 0) && (g.GL_PRSA == V.WAIT_FOR || g.GL_PRSA == V.WAIT)) {
    ret = true;
  } else if ((g.GL_PRSA == V.WAIT_FOR || g.GL_PRSA == V.WAIT) && !(g.GL_PLACE_CUR == RM_CLOCK_TOWER)) {
    await RT_DO_CLOCK_SET(GL_TIME_UPDT_INC, 1, 0, 0);
    await RT_CLOCK_INC();
    if (eq(await RT_CLOCK_CMP(getb(GL_TEMP_TIME, K_HRS), getb(GL_TEMP_TIME, K_MIN), getb(GL_TEMP_TIME, K_SEC), getb(GL_TEMP_TIME, K_DAY)), 1)) {
      if (g.GL_WAIT_BELL == 0) {
        tell("\nWhile you wait, you hear Big Ben strike each hour.\n");
      }
      ret = true;
    }
    await RT_DO_CLOCK_SET(GL_TIME_UPDT_INC, -1, 0, 0);
    await RT_CLOCK_INC();
    g.GL_WAIT_BELL = true;
  } else {
    g.GL_WAIT_BELL = false;
  }
  await RT_ALARM_SET_REL(RT_I_BIGBEN.id, await RT_DO_CLOCK_SET(GL_TIME_PARM, 1, 0, 0));
  if (!(ret == 0)) {
    return false;
  }
  hrs = getb(GL_TIME, K_HRS);
  if (!(g.GL_PLACE_CUR == RM_CLOCK_TOWER)) {
    tell("\nIn the distance, you hear Big Ben strike the hour.\n");
    if (!g.SOUND_QUEUED$) {
      if (s16(hrs) > s16(12)) {
        g.TH_BELL_AUX1 = hrs - 12;
      } else {
        g.TH_BELL_AUX1 = hrs;
      }
      return await SOUNDS(S_FARBEN, S_START, 3, g.TH_BELL_AUX1);
    } else {
      return false;
    }
  } else {
    if (s16(hrs) > s16(12)) {
      g.TH_BELL_AUX1 = hrs - 12;
    } else {
      g.TH_BELL_AUX1 = hrs;
    }
    return await RT_I_SWING_BELL();
  }
}

async function RT_I_SWING_BELL() {
  let obj = 0, num = 0, pos = 0, who = 0;
  num = g.TH_BELL_AUX1;
  pos = g.TH_BELL_AUX2;
  if (!(g.GL_PLACE_CUR == RM_CLOCK_TOWER)) {
    await RT_RELIEF();
    g.HEARD_SWING$ = false;
    g.TH_BELL_AUX1 = 0;
    g.TH_BELL_AUX2 = K_BELL_AWAY;
    await RT_ZERO_SECONDS();
    return false;
  }
  if (s16(num) > s16(0)) {
    await RT_DO_CLOCK_SET(GL_TIME_UPDT_INC, 0, 0, 2);
    await RT_ALARM_SET_REL(RT_I_SWING_BELL.id, await RT_DO_CLOCK_SET(GL_TIME_PARM, 0, 0, 2));
  }
  if (!g.HEARD_SWING$) {
    await SOUNDS(S_CLOCK, S_INIT);
  }
  tell("\nThe bell swings ");
  if (pos == K_BELL_AWAY) {
    g.TH_BELL_AUX2 = K_BELL_TOWARDS;
    tell("towards you, ");
    if (hasFlag(TH_COTTON_BALLS, FL_WORN)) {
      tell("ringing loudly, but the cotton protects your ears");
      who = await RT_WHO_SAYS$();
      if (who && !g.HEARD_SWING$) {
        tell(". ");
        await RT_CTHEO_PRINT(who);
        tell(" claps his hands to his ears in an attempt to protect them");
        if (first(who)) {
          await RT_MOVE_ALL(who, RM_CLOCK_TOWER);
          tell(", dropping everything he was carrying in the process");
        }
      }
      tell(". The clapper swings up within reach.\n");
      await SOUNDS(S_CLOCK, S_START, 6);
      g.HEARD_SWING$ = true;
    } else {
      tell("ringing unbearably loud. BONG!");
      await SOUNDS(S_CLOCK);
      if (!g.HEARD_SWING$ && !(hasFlag(TH_HANDS, FL_LOCKED))) {
        g.HEARD_SWING$ = true;
        who = await RT_WHO_SAYS$();
        setFlag(TH_HANDS, FL_LOCKED);
        await RT_MOVE_ALL_BUT_WORN(CH_PLAYER, RM_CLOCK_TOWER);
        tell(" You ");
        if (who) {
          await RT_MOVE_ALL(who, RM_CLOCK_TOWER);
          tell("and ");
          await DPRINT(who);
          tell(" ");
        }
        tell("clap your hands to your ears in an attempt to protect them, dropping everything you are carrying in the process.");
      }
      crlf();
    }
    return g.TH_BELL_AUX1 = num - 1;
  } else {
    g.TH_BELL_AUX2 = K_BELL_AWAY;
    tell("away from you");
    if (num == 0) {
      tell(", finishing the ringing of the hour.\n");
      await RT_RELIEF();
      return await RT_ZERO_SECONDS();
    } else {
      tell(".\n");
      return true;
    }
  }
}

