async function RT_ETHERIUM_EFFECT(asleep$, obj = false, top = true) {
  let cnt = 0;
  if (obj == 0) {
    obj = g.GL_PLACE_CUR;
  }
  loop1: for (;;) {
    if (obj == 0) {
      break loop1;
    } else if (hasFlag(obj, FL_ALIVE) && (!(obj == CH_PLAYER) || !(hasFlag(TH_BREATH, FL_LOCKED)))) {
      if (!(asleep$ == 0)) {
        if (!(obj == CH_HOLMES) || !(hasFlag(TH_BREATH, FL_LOCKED))) {
          setFlag(obj, FL_ASLEEP);
          ++cnt;
          if (g.GL_PUPPY == obj) {
            g.GL_FORMER_PUPPY = obj;
            g.GL_PUPPY = false;
          }
        }
      } else {
        clearFlag(obj, FL_ASLEEP);
        ++cnt;
      }
    } else if (first(obj)) {
      cnt = cnt + (await RT_ETHERIUM_EFFECT(asleep$, first(obj), false));
    }
    if (top == 0) {
      obj = next(obj);
    } else {
      break loop1;
    }
  }
  return cnt;
}

