async function RT_I_MOVE_DOWNSTREAM() {
  if ((g.GL_WINNER == CH_PLAYER) && (g.GL_PRSA == V.ROW)) {
    (await RT_CYOU_MSG("row", "rows"));
  } else if ((g.GL_WINNER == CH_PLAYER) && (g.GL_PRSA == V.PADDLE || g.GL_PRSA == V.PADDLE_WITH)) {
    (await RT_CYOU_MSG("paddle", "paddles"));
  } else {
    tell("\nThe boat drifts ");
  }
  tell("down the river");
  g.GL_NOW_LIT$ = await RT_IS_LIT$();
  if (eq(loc(TH_BOAT), RM_THAMES_ONE, RM_THAMES_TWO, RM_THAMES_THREE, RM_THAMES_FOUR)) {
    tell(". ");
  }
  if (loc(TH_BOAT) == RM_THAMES_ONE) {
    move(TH_BOAT, RM_THAMES_TWO);
    if (!(g.GL_NOW_LIT$ == 0)) {
      tell("Downstream you see the London Bridge.");
    }
  } else if (loc(TH_BOAT) == RM_THAMES_TWO) {
    move(TH_BOAT, RM_THAMES_THREE);
    if (!(g.GL_NOW_LIT$ == 0)) {
      tell("You pass under the London Bridge.");
    }
  } else if (loc(TH_BOAT) == RM_THAMES_THREE) {
    move(TH_BOAT, RM_THAMES_FOUR);
    if (!(g.GL_NOW_LIT$ == 0)) {
      tell("To the north you see the Traitors Gate.");
    }
  } else if (loc(TH_BOAT) == RM_THAMES_FOUR) {
    move(TH_BOAT, RM_THAMES_FIVE);
    if (!(g.GL_NOW_LIT$ == 0)) {
      tell("Downstream you see the open seas... the strong currents would surely leave you stranded in your small boat if you were to drift further.");
    }
  } else if (loc(TH_BOAT) == RM_THAMES_FIVE) {
    tell(", and you drift out to sea.\n\nAfter drifting for several days, a passing ship rescues you. By coincidence, another passenger happens to be Lestrade, who has resigned in the wake of the Crown Jewel scandal and is retiring to the island of Pago Pago. After some reflection, you decide to join him.\n\n");
    await RT_QSR();
  }
  g.GL_PLACE_CUR = loc(TH_BOAT);
  return crlf();
}

async function RT_MOVE_UPSTREAM() {
  tell("Fighting against the current, you ", wordText(g.GL_P_PRSA_WORD), " upstream. ");
  g.GL_NOW_LIT$ = await RT_IS_LIT$();
  if (loc(TH_BOAT) == RM_THAMES_ONE) {
    tell("\n\nAs you proceed you find yourself among the flotilla of warships that have come for the celebration of the Jubilee. You quickly decide that it's too dangerous here so you turn back and head downstream.");
  } else if (loc(TH_BOAT) == RM_THAMES_TWO) {
    if (!(g.GL_NOW_LIT$ == 0)) {
      tell("To the north you see the Embankment.");
    }
    move(TH_BOAT, RM_THAMES_ONE);
  } else if (loc(TH_BOAT) == RM_THAMES_THREE) {
    move(TH_BOAT, RM_THAMES_TWO);
  } else if (loc(TH_BOAT) == RM_THAMES_FOUR) {
    if (!(g.GL_NOW_LIT$ == 0)) {
      tell("You pass under the London Bridge.");
    }
    move(TH_BOAT, RM_THAMES_THREE);
  } else if (loc(TH_BOAT) == RM_THAMES_FIVE) {
    if (!(g.GL_NOW_LIT$ == 0)) {
      tell("Upstream, you see the London Bridge, to the north you see the Traitors Gate.");
    }
    move(TH_BOAT, RM_THAMES_FOUR);
  }
  crlf();
  g.GL_PLACE_CUR = loc(TH_BOAT);
  return true;
}

