async function RT_TOWER_PASSWORD(word_num) {
  let password = 0;
  password = g.PASSWORD_ID;
  if ((password == 0) || !(g.GL_PLACE_CUR == RM_BYWARD_TOWER)) {
    tell("Wasn't she one of the six wives of Henry VIII?\n");
    return true;
  } else if (g.GL_PLACE_PRV == RM_OUTER_WARD) {
    tell("\"I am sorry, but I have strict orders to allow absolutely no one to leave the Tower, whether or not he knows the password. The Prime Minister himself could not get out of here before Monday morning.\n");
    return true;
  } else if (!(word_num == password)) {
    tell("\"I am sorry but that password is no longer valid.\"\n");
    return true;
  } else {
    tell("The guard steps aside as you walk in.\n\n");
    await RT_GOTO(RM_OUTER_WARD);
    await RT_UPDATE_SCORE(3);
    g.PASSWORD_ID = 9;
    g.ALLOW_IN_TOWER = true;
    return true;
  }
}

