async function RT_AC_LG_WATER(context = false, class_ = false, cap$ = false) {
  if (context == K_M_SDESC) {
    (await PRINT_SDESC("water", class_, class_ == K_DESC_A ? true : false, false));
    return true;
  } else if (!!context) {
    return false;
  } else if (g.GL_NOW_PRSI$ == 0) {
    if (g.GL_PRSA == V.ENTER || g.GL_PRSA == V.LEAP) {
      if (g.GL_WINNER == CH_PLAYER) {
        tell("You may not remember this, but you can't swim.\n");
        return true;
      } else {
        tell("That's not very polite.\n");
        return true;
      }
    } else if (g.GL_PRSA == V.DRINK) {
      tell(S(K_YUCK_MSG), "\n");
      return true;
    } else if (g.GL_PRSA == V.EXAMINE) {
      tell("The water is black, oily, slimy, dirty, and otherwise unwholesome-looking.\n");
      return true;
    } else if (g.GL_PRSA == V.LOOK_INSIDE || g.GL_PRSA == V.SEARCH) {
      tell("The water is so black and oily that you can't see a thing.\n");
      return true;
    } else if (g.GL_PRSA == V.REACH_IN || g.GL_PRSA == V.SEARCH) {
      tell("Slimy things brush up against your hand, so you quickly pull it back.\n");
      return true;
    } else if (g.GL_PRSA == V.SHOOT) {
      return await RT_WASTE_OF_BULLETS_MSG();
    } else {
      return false;
    }
  } else if (!(g.GL_NOW_PRSI$ == 0)) {
    if (g.GL_PRSA == V.PUT || g.GL_PRSA == V.PUT_ON) {
      if (hasFlag(g.GL_PRSO, FL_BODYPART) || (g.GL_PRSO == CH_ME || g.GL_PRSO == CH_PLAYER)) {
        tell(S(K_YUCK_MSG), "\n");
        return true;
      } else {
        if ((g.GL_PRSO == TH_ANCHOR || g.GL_PRSO == PSEUDO_OBJECT) || eq(loc(g.GL_PRSO), GLOBAL_OBJECTS, LOCAL_GLOBALS)) {
          await RT_PERFORM(V.DROP, g.GL_PRSO);
          return true;
        } else if (g.GL_PRSO == CH_TRAINED_PIGEON) {
          remove(g.GL_PRSO);
          await RT_KILL_PIGEON();
          tell("The pigeon struggles briefly, its feathers too wet to fly, then sinks below the water.");
          return true;
        } else {
          remove(g.GL_PRSO);
          clearFlag(g.GL_PRSO, FL_WORN);
          tell("Plop.\n");
          return true;
        }
      }
    } else {
      return false;
    }
  } else {
    return false;
  }
}

