async function RT_AC_LG_PLAQUES(context = false) {
  if (context == K_M_DESCFCN) {
    tell("It looks mighty like a plaque.\n");
    return true;
  } else if (g.GL_PRSA == V.TAKE) {
    tell("The plaque is firmly attached to the ");
    if (g.GL_PLACE_CUR == RM_MANUSCRIPT_ROOM) {
      tell("desk");
    } else {
      tell("wall");
    }
    tell(". You can't remove it.\n");
    return true;
  } else if (g.GL_PRSA == V.READ || g.GL_PRSA == V.EXAMINE) {
    if (g.GL_PLACE_CUR == RM_BROAD_SANCTUARY) {
      g.GL_WINDOW = get(GL_QUOTES, K_SIGN_ABBEY);
    } else if (g.GL_PLACE_CUR == RM_MANUSCRIPT_ROOM) {
      g.GL_WINDOW = get(GL_QUOTES, K_SIGN_QUIET);
    } else if (g.GL_PLACE_CUR == RM_MADAME_TUSSAUDS) {
      g.GL_WINDOW = get(GL_QUOTES, K_SIGN_HORRORS);
    } else if (g.GL_PLACE_CUR == RM_GREAT_RUSSELL_ST) {
      g.GL_WINDOW = get(GL_QUOTES, K_SIGN_MUSEUM);
    } else if (g.GL_PLACE_CUR == RM_MONUMENT) {
      g.GL_WINDOW = get(GL_QUOTES, K_SIGN_MONUMENT);
    } else if (g.GL_PLACE_CUR == RM_THE_BLACK_MUSEUM) {
      g.GL_WINDOW = get(GL_QUOTES, K_SIGN_BLIGH);
    } else if (g.GL_PLACE_CUR == RM_THREADNEEDLE_ST) {
      g.GL_WINDOW = get(GL_QUOTES, K_SIGN_BANK);
    } else if (g.GL_PLACE_CUR == RM_TOWER_ENTRANCE) {
      g.GL_WINDOW = get(GL_QUOTES, K_SIGN_TOWER);
    } else if (g.GL_PLACE_CUR == RM_TRAFALGAR_SQUARE) {
      g.GL_WINDOW = get(GL_QUOTES, K_SIGN_NELSON);
    } else if (g.GL_PLACE_CUR == RM_VICTORIA_STREET) {
      g.GL_WINDOW = get(GL_QUOTES, K_SIGN_LOITER);
    } else if (g.GL_PLACE_CUR == RM_SWAN_LANE) {
      g.GL_WINDOW = get(GL_QUOTES, K_SIGN_GOLDBAR);
    } else if (g.GL_PLACE_CUR == RM_JERUSALEM_CHAMBER) {
      g.GL_WINDOW = get(GL_QUOTES, K_SIGN_HENRY);
    } else {
      g.GL_WINDOW = get(GL_QUOTES, K_SIGN_BLANK);
    }
    await RT_WINDOW(g.GL_WINDOW);
    g.GL_WINDOW = false;
    return true;
  } else if ((g.GL_PRSA == V.PUT || g.GL_PRSA == V.PUT_ON) && !(g.GL_NOW_PRSI$ == 0)) {
    tell("Putting anything on ");
    await RT_THEO_PRINT(LG_PLAQUES);
    tell(" would");
    return await RT_WASTE_OF_TIME_MSG();
  } else {
    return false;
  }
}

async function RT_DF_LG_WAX_STATUES(context = false, class_ = false) {
  if (context == K_M_SDESC) {
    (await PRINT_SDESC("statues", class_, false, true));
    return true;
  } else if (context == K_M_DESCFCN) {
    if (g.GL_PLACE_CUR == RM_MADAME_TUSSAUDS) {
      tell("The statues are of King John, Sir Francis Drake, Sir Walter Raleigh, and William the Conqueror.\n");
      return true;
    } else if (g.GL_PLACE_CUR == RM_CHAMBER_OF_HORRORS) {
      tell("The statues are of Guy Fawkes, Charles I, and Saint Thomas Becket.\n");
      return true;
    } else {
      return false;
    }
  } else {
    return false;
  }
}

async function RT_AC_LG_WINDOW(context = false) {
  if (context == K_M_DESCFCN) {
    if (g.GL_PLACE_CUR == RM_221B_BAKER_ST) {
      tell("It is a bow window, far above your head.\n");
      return true;
    } else if (g.GL_PLACE_CUR == RM_SOUTH_TRANSEPT) {
      tell("It is the largest rose window in all England");
      if (eq(await RT_TIME_OF_DAY(), 1, 2, 3)) {
        tell(S(K_BRIGHTENS_UP_MSG));
      }
      tell(".\n");
      return true;
    } else if (g.GL_PLACE_CUR == RM_NORTH_TRANSEPT) {
      tell("It is set high in the north wall of the Abbey");
      if (eq(await RT_TIME_OF_DAY(), 1, 2, 3)) {
        tell(S(K_BRIGHTENS_UP_MSG));
      }
      tell(".\n");
      return true;
    } else {
      return false;
    }
  } else if ((g.GL_PRSA == V.SHOOT) && (g.GL_NOW_PRSI$ == 0)) {
    return await RT_WASTE_OF_BULLETS_MSG();
  } else if ((loc(g.GL_WINNER) == RM_SOUTH_TRANSEPT) || (loc(g.GL_WINNER) == RM_NORTH_TRANSEPT)) {
    if (g.GL_PRSA == V.LOOK_INSIDE || g.GL_PRSA == V.SEARCH || g.GL_PRSA == V.LOOK_OUTSIDE) {
      tell("You cannot see through the stained-glass window.\n");
      return true;
    } else if (await RT_TOUCH_VERB$()) {
      await RT_CTHEO_PRINT(LG_WINDOW);
      tell(" is too high.\n");
      return true;
    } else {
      return false;
    }
  } else if (loc(g.GL_WINNER) == RM_221B_BAKER_ST) {
    if (await RT_TOUCH_VERB$()) {
      await RT_CTHEO_PRINT(LG_WINDOW);
      tell(" is too high.\n");
      return true;
    } else if (g.GL_PRSA == V.LOOK_INSIDE || g.GL_PRSA == V.LOOK_OUTSIDE || g.GL_PRSA == V.SEARCH) {
      await RT_CTHEO_PRINT(LG_WINDOW);
      tell(" is too high to see in.\n");
      return true;
    } else {
      return false;
    }
  } else if (loc(g.GL_WINNER) == RM_HOLMES_STUDY) {
    if (g.GL_PRSA == V.LOOK_INSIDE || g.GL_PRSA == V.LOOK_OUTSIDE || g.GL_PRSA == V.SEARCH) {
      tell("You look down into Baker Street.\n");
      return await RT_DESCRIBE_PLACE_CONTENTS(RM_221B_BAKER_ST);
    } else if (g.GL_PRSA == V.MUNG) {
      await RT_CTHEO_PRINT(LG_WINDOW);
      tell(" is made of reinforced glass. It can't be broken.\n");
      return true;
    } else if (g.GL_PRSA == V.OPEN) {
      await RT_CTHEO_PRINT(LG_WINDOW);
      tell(" is jammed shut. It can't be opened.\n");
      return true;
    } else {
      return false;
    }
  } else {
    return false;
  }
}

async function RT_AC_LG_TOMBS_ABBEY(context = false) {
  if (eq(getProp(LG_TOMBS_ABBEY, P.OBJ_NOUN), W.ABBEY)) {
    if (context == K_M_SDESC) {
      tell("Abbey");
      return true;
    } else if (!!context) {
      return false;
    } else if (g.GL_PRSA == V.ENTER) {
      if (g.GL_PLACE_CUR == RM_NAVE) {
        return await RT_ALREADY_IN_ROOM_MSG();
      } else if (g.GL_PLACE_CUR == RM_BROAD_SANCTUARY) {
        return await RT_DO_WALK(P.EAST);
      } else {
        return false;
      }
    } else if (g.GL_PRSA == V.EXIT) {
      if (g.GL_PLACE_CUR == RM_NAVE) {
        return await RT_DO_WALK(P.WEST);
      } else {
        return await RT_NOT_IN_ROOM_MSG();
      }
    } else if (g.GL_PRSA == V.SHOOT) {
      return await RT_IMPOSSIBLE_MSG();
    } else {
      return false;
    }
  } else {
    if (context == K_M_SDESC) {
      tell("tombs");
      return true;
    } else if (!(hasFlag(g.GL_PLACE_CUR, FL_INDOORS)) || (g.GL_PLACE_CUR == RM_JERICHO_PARLOUR || g.GL_PLACE_CUR == RM_JERUSALEM_CHAMBER || g.GL_PLACE_CUR == RM_NORTH_CLOISTER)) {
      await RT_CANT_SEE_ANY_MSG(LG_TOMBS_ABBEY);
      return true;
    } else if (context == K_M_DESCFCN) {
      if (g.GL_PLACE_CUR == RM_SOUTH_AMBULATORY || g.GL_PLACE_CUR == RM_NORTH_AMBULATORY) {
        tell("There are so many of them! None stands out in particular.\n");
        return true;
      } else if (g.GL_PLACE_CUR == RM_CONFESSOR_CHAPEL) {
        tell("Two of them are especially interesting. One is the tomb of Edward the Confessor. The other is of Henry V.\n");
        return true;
      } else {
        tell("One tomb in particular catches your eye.\n");
        return true;
      }
    } else if (g.GL_NOW_PRSI$ == 0) {
      if (g.GL_PRSA == V.SHOOT) {
        return await RT_SHOOT_DEAD_MSG();
      } else {
        return false;
      }
    } else {
      return false;
    }
  }
}

